void main() {
  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();
    final MockSettingsRepository mockSettingsRepository = MockSettingsRepository();

    late Widget dashboardWidget;

    setUp(() {
      dashboardWidget = buildWidget(
        providers: [
          Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          Provider<NewsRepository>.value(value: mockNewsRepository),
          Provider<SettingsRepository>.value(value: mockSettingsRepository),
        ],
        child: const DashboardPage(),
      );

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => const CurrencyPage(
          items: [
            CurrencyModel(
              id: '1',
              nominal: 1,
              name: 'Доллар США',
              symbol: '$',
              value: 92.50,
              previousValue: 91.80,
            ),
          ],
          page: 0,
          hasMore: false,
        ),
      );

      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer(
        (_) async => [
          NewsModel(
            title: 'Новость экономики',
            link: 'https://example.com/news/1',
            date: DateTime(2025, 1, 1),
          ),
        ],
      );

      when(mockSettingsRepository.readThemeMode()).thenReturn(AppThemeMode.system);
    });

    testWidgets('should display CircularProgressIndicator while loading', (WidgetTester tester) async {
      await tester.pumpWidget(dashboardWidget);
      await tester.pump();

      expect(find.byType(CircularProgressIndicator), findsOneWidget);
    });

    testWidgets('should show dashboard title and data after loading', (WidgetTester tester) async {
      await tester.pumpWidget(dashboardWidget);
      await tester.pumpAndSettle();

      // Check for the AppBar with Dashboard title
      expect(find.text('Дашборд'), findsOneWidget);

      // Check that currency data is displayed
      expect(find.text('Доллар США'), findsOneWidget);
      expect(find.text('92.50'), findsOneWidget);

      // Check that news data is displayed
      expect(find.text('Новость экономики'), findsOneWidget);
    });

    testWidgets('should display empty state when no currencies are available', (WidgetTester tester) async {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => const CurrencyPage(items: [], page: 0, hasMore: false),
      );

      await tester.pumpWidget(dashboardWidget);
      await tester.pumpAndSettle();

      expect(find.text('Дашборд'), findsOneWidget);
    });

    testWidgets('should display empty state when no news are available', (WidgetTester tester) async {
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer(
        (_) async => [],
      );

      await tester.pumpWidget(dashboardWidget);
      await tester.pumpAndSettle();

      expect(find.text('Дашборд'), findsOneWidget);
    });

    testWidgets('should use Future.wait for parallel data loading', (WidgetTester tester) async {
      var fetchCount = 0;
      var loadNewsCount = 0;

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async {
        fetchCount++;
        await Future.delayed(const Duration(milliseconds: 100));
        return const CurrencyPage(items: [], page: 0, hasMore: false);
      });

      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async {
        loadNewsCount++;
        await Future.delayed(const Duration(milliseconds: 50));
        return [];
      });

      await tester.pumpWidget(dashboardWidget);
      await tester.pump();

      // Allow some time for futures to start
      await tester.pump(const Duration(milliseconds: 10));

      // Both should have been started by now (even if not completed)
      expect(fetchCount, equals(1));
      expect(loadNewsCount, equals(1));

      await tester.pumpAndSettle();
    });
  });
}
