import 'package:mad_flutter_practicum/domain/domain.dart';
import 'widgets/dashboard_currency_row.dart';
import 'widgets/dashboard_news_card.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> with SingleTickerProviderStateMixin {
  late Future<Map<String, dynamic>> _dashboardDataFuture;
  late final AnimationController _fadeController;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    // Параллельный запрос свежих данных через Future.wait
    _dashboardDataFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((results) {
      if (!mounted) return {};

      final CurrencyPage currencyPage = results[0] as CurrencyPage;
      final List<NewsModel> newsList = results[1] as List<NewsModel>;

      _fadeController.forward(); // запускаем анимацию появления

      return <String, dynamic>{
        'currencyPage': currencyPage,
        'newsList': newsList,
      };
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<Map<String, dynamic>>(
        future: _dashboardDataFuture,
        builder: (BuildContext context, AsyncSnapshot<Map<String, dynamic>> snapshot) {
          // Индикатор прогресса пока грузятся данные
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(
              child: CircularProgressIndicator(),
            );
          }

          if (!snapshot.hasData || snapshot.data == null) {
            return Center(
              child: Text(
                loc.error,
                style: fonts.regular16,
              ),
            );
          }

          final CurrencyPage currencyPage = snapshot.data!['currencyPage'] as CurrencyPage;
          final List<NewsModel> newsList = snapshot.data!['newsList'] as List<NewsModel>;

          return FadeTransition(
            opacity: _fadeController.view,
            child: SingleChildScrollView(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Секция с курсами валют
                  Text(
                    loc.currencyRate,
                    style: fonts.semiBold12,
                  ),
                  const SizedBox(height: 8),
                  if (currencyPage.items.isEmpty)
                    Center(
                      child: Text(
                        'Нет данных',
                        style: fonts.regular16,
                      ),
                    )
                  else
                    ListView.builder(
                      shrinkWrap: true,
                      physics: const NeverScrollableScrollPhysics(),
                      itemCount: currencyPage.items.length > 5 ? 5 : currencyPage.items.length,
                      itemBuilder: (BuildContext context, int index) {
                        final CurrencyModel currency = currencyPage.items[index];
                        return DashboardCurrencyRow(currency: currency);
                      },
                    ),
                  const SizedBox(height: 24),

                  // Секция с новостями
                  Text(
                    loc.news,
                    style: fonts.semiBold12,
                  ),
                  const SizedBox(height: 8),
                  if (newsList.isEmpty)
                    Center(
                      child: Text(
                        'Нет данных',
                        style: fonts.regular16,
                      ),
                    )
                  else
                    ListView.builder(
                      shrinkWrap: true,
                      physics: const NeverScrollableScrollPhysics(),
                      itemCount: newsList.length > 5 ? 5 : newsList.length,
                      itemBuilder: (BuildContext context, int index) {
                        final NewsModel news = newsList[index];
                        return Padding(
                          padding: const EdgeInsets.only(bottom: 8),
                          child: DashboardNewsCard(model: news),
                        );
                      },
                    ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }
}
