import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/model/news_model.dart';
import 'package:url_launcher/url_launcher.dart';

class DashboardNewsCard extends StatelessWidget {
  const DashboardNewsCard({super.key, required this.model});

  final NewsModel model;

  @override
  Widget build(BuildContext context) {
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return GestureDetector(
      onTap: () async {
        final Uri url = Uri.parse(model.link);
        if (await canLaunchUrl(url)) {
          await launchUrl(url, mode: LaunchMode.externalApplication);
        }
      },
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 8),
        decoration: BoxDecoration(
          color: colors.cardColor,
          borderRadius: BorderRadius.circular(8),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              model.title,
              style: fonts.regular16,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
            ),
            if (model.date != null) ...[
              const SizedBox(height: 4),
              Text(
                DateFormat('dd.MM.yyyy').format(model.date!),
                style: fonts.regular12.copyWith(color: colors.tin),
              ),
            ],
          ],
        ),
      ),
    );
  }
}
